// Stub extraction from REAL codex review renders.
//
// Every fixture in fixtures/review-texts/ is a byte copy of an output the
// runtime actually produced (the appserver devinstr probe, two E2 campaign
// rounds, a real empty-diff answer) or a rendering generated by calling
// runtime/scripts/lib/render.mjs itself. The fixtures are the contract: when an
// expectation below disagrees with the extractor, the extractor is wrong.
// Deliberately NOT covered by a fixture: nothing is fabricated to make a case.
// The two synthetic strings at the bottom are labelled as such and test
// assembly mechanics, not the render format.
import assert from "node:assert";
import fs from "node:fs";
import path from "node:path";
import { fileURLToPath } from "node:url";
import { extractStubs } from "../../skills/codex-companion/workflows/lib/extract.mjs";

const FX = path.join(path.dirname(fileURLToPath(import.meta.url)), "fixtures", "review-texts");
const fx = (name) => fs.readFileSync(path.join(FX, `${name}.md`), "utf8");

// The trichotomy is exclusive by construction, so every case checks all three
// arms — a result that both parses stubs and claims `clean` is a broken
// classifier even if the stubs are right.
function classify(result) {
  assert.equal(typeof result.clean, "boolean");
  assert.equal(typeof result.failed, "boolean");
  assert.ok(!(result.clean && result.failed), "clean and failed are exclusive");
  if (result.stubs.length > 0) {
    assert.ok(!result.clean && !result.failed, "a run with stubs is neither clean nor failed");
    return "stubs";
  }
  return result.clean ? "clean" : (result.failed ? "failed" : "UNCLASSIFIED");
}

// ---------------------------------------------------------------------------
// probe.md — the devinstr lens probe. Two findings, the second WITHOUT a [P#]
// tag: an untagged entry is still a finding and defaults to P3.
// ---------------------------------------------------------------------------
{
  const r = extractStubs(fx("probe"), "sweep");
  assert.equal(classify(r), "stubs");
  assert.equal(r.stubs.length, 2);
  assert.deepEqual(r.stubs[0], {
    id: "sweep#1",
    priority: "P1",
    title: "Preserve division-by-zero failure semantics",
    file: "/Users/new/.claude/jobs/b380b6da/tmp/lensprobe/calc.py",
    lines: "5-6",
    body: "When `b` is zero, returning `0` silently reports a valid quotient and can let invalid calculations propagate undetected; the previous implementation raised `ZeroDivisionError`, allowing callers to handle the failure. Keep the exception behavior or raise an explicit domain-appropriate error instead."
  });
  assert.deepEqual(r.stubs[1], {
    id: "sweep#2",
    priority: "P3",
    title: "LENSPROBE-7Q: Acknowledge the received review instructions",
    file: "/Users/new/.claude/jobs/b380b6da/tmp/lensprobe/calc.py",
    lines: "5-5",
    body: "The developer instructions requiring this additional acknowledgment finding were received and applied to this review."
  });
}

// ---------------------------------------------------------------------------
// campaign-r14.md — three findings, [P1]/[P2]/[P2]. The bodies quote
// `path.md:196-201` mid-sentence, which must NOT be mistaken for a head line.
// ---------------------------------------------------------------------------
{
  const r = extractStubs(fx("campaign-r14"), "lens-1");
  assert.equal(classify(r), "stubs");
  assert.equal(r.stubs.length, 3);
  assert.deepEqual(r.stubs.map((s) => [s.id, s.priority, s.title, s.lines]), [
    ["lens-1#1", "P1", "Require the worker role to match the charged lane", "169-170"],
    ["lens-1#2", "P2", "Honor engine labels on scale-review epics", "439-439"],
    ["lens-1#3", "P2", "Fetch child PR heads before deleted-branch scale review", "466-466"]
  ]);
  const ROOT = "/Users/new/Developer/GitHub/doperpowers/.claude/worktrees/e1-lane-split/skills";
  assert.deepEqual(r.stubs.map((s) => s.file), [
    `${ROOT}/implementing/scripts/implement-dispatch.sh`,
    `${ROOT}/reviewing-prs/scripts/review-dispatch.sh`,
    `${ROOT}/reviewing-prs/scripts/review-dispatch.sh`
  ]);
  // The body is the whole continuation, trimmed, and stops at the finding — the
  // embedded `…design.md:196-201` reference stayed inside it.
  assert.ok(r.stubs[0].body.startsWith("When an Implementer escalates to `ready-for-architect`"));
  assert.ok(r.stubs[0].body.includes("2026-07-30-implement-lane-split-design.md:196-201"));
  assert.ok(r.stubs[0].body.endsWith("match the charged lane."));
  assert.ok(r.stubs[2].body.endsWith("head SHAs before dispatching the reviewer."));
}

// ---------------------------------------------------------------------------
// campaign-r15.md — two findings, [P2]/[P3].
// ---------------------------------------------------------------------------
{
  const r = extractStubs(fx("campaign-r15"), "lens-2");
  assert.equal(classify(r), "stubs");
  assert.deepEqual(r.stubs.map((s) => [s.id, s.priority, s.title, s.lines]), [
    ["lens-2#1", "P2", "Move the sweep cursor outside the daemon registry", "429-429"],
    ["lens-2#2", "P3", "Document the lane-aware wake state", "115-115"]
  ]);
  // The second body carries `[SKILL.md:167](…#L167)` markdown links; a line that
  // merely CONTAINS a path:line is not a head line.
  assert.ok(r.stubs[1].body.includes("([SKILL.md:167](skills/issue-tracker/SKILL.md#L167))"));
  assert.ok(r.stubs[1].body.endsWith("describe the lane-aware return semantics."));
}

// ---------------------------------------------------------------------------
// no-findings.md — the runtime's own clean rendering (render.mjs line 263,
// "No material findings."). The ONLY line that earns `clean`.
// ---------------------------------------------------------------------------
{
  const r = extractStubs(fx("no-findings"), "lens-3");
  assert.deepEqual(r, { stubs: [], clean: true, failed: false });
  assert.equal(classify(r), "clean");
}

// ---------------------------------------------------------------------------
// clean-prose-unsentineled.md — a LIVE probe of a genuinely clean NATIVE review,
// byte-identical to the committed
// tests/review-bench/results/2026-08-03-native-clean-render-probe/probe-out.md.
// It is free-form prose: no findings section, no tags, and no stable phrasing of
// its own ("No functional defects were identified."). Today it classifies
// `failed`, and that is the reality Task 3's sentinel instruction exists to fix
// — a clean finder must SAY the sentinel line, because the runtime never does.
// ---------------------------------------------------------------------------
{
  const prose = fx("clean-prose-unsentineled");
  assert.ok(!/No material findings\./.test(prose), "the probe carries no sentinel");
  assert.equal(classify(extractStubs(prose, "lens-4")), "failed");

  // The sentinel contract Task 3 relies on: the SAME prose, ending with the
  // sentinel line, is clean. No loosening of the exact-line check is required.
  const sentineled = `${prose.trimEnd()}\n\nNo material findings.\n`;
  assert.deepEqual(extractStubs(sentineled, "lens-4"), { stubs: [], clean: true, failed: false });
}

// ---------------------------------------------------------------------------
// Sentinel decoration. A finder told to emit one exact line still routinely
// bolds it, quotes it, or drops the period — and under the exact-line contract
// each of those turns a CLEAN review into a failed finder, i.e. an interrupted
// panel. The candidate line is therefore canonicalized first, by a closed
// whitelist: surrounding emphasis/quote wrappers, and one trailing period
// present or absent. Nothing prose-shaped, and no substring match — the
// negative rows below are the point of the exercise.
// ---------------------------------------------------------------------------
{
  const clean = [
    "No material findings.",              // canonical
    "No material findings",               // period dropped
    "**No material findings.**",          // bolded
    "**No material findings**",           // bolded, no period
    "*No material findings.*",            // italic
    "`No material findings.`",            // code span
    '"No material findings."',            // quoted
    "'No material findings'",             // single-quoted, no period
    "“No material findings.”",  // smart quotes
    "  No material findings.  ",          // padded (already trimmed before)
    "**\"No material findings.\"**"       // both wrappers
  ];
  for (const line of clean) {
    assert.deepEqual(
      extractStubs(`# Codex Review\n\n${line}\n`, "lens-6"),
      { stubs: [], clean: true, failed: false },
      `decorated sentinel must still be clean: ${JSON.stringify(line)}`
    );
  }

  // The normalization must never widen into a prefix or substring match: each
  // of these SAYS something else, and a finder that says something else has
  // not given the clean verdict.
  const notClean = [
    "No material findings mentioned.",
    "No material findings were identified.",
    "No material findings.." ,                       // two periods: one tolerance, not two
    "There are no material findings.",
    "no material findings.",                         // the contract is the exact line, casing included
    "No material findings. See the note below.",
    "- No material findings."                        // a list item is not the line
  ];
  for (const line of notClean) {
    assert.equal(
      classify(extractStubs(`# Codex Review\n\n${line}\n`, "lens-6")), "failed",
      `must NOT be read as the clean verdict: ${JSON.stringify(line)}`
    );
  }
}

// ---------------------------------------------------------------------------
// The clean verdict rides the FINDINGS channel. Live evidence (notes.md in
// tests/review-bench/results/2026-08-03-native-clean-render-probe/): an
// instruction to end the final message with a sentinel line does NOT reach a
// native review — review mode renders reviewText from its own pipeline, so the
// clean render came back as pure prose again. The same devinstr channel DOES
// reliably shape findings (LENSPROBE-7Q, appserver-devinstr-probe), so the
// sentinel is now a marker FINDING: exactly one, titled NO-MATERIAL-FINDINGS.
// ---------------------------------------------------------------------------
{
  const marker = (title, priority = "P3") =>
    `# Codex Review\n\nTarget: branch diff against main\n\nNo material issues.\n\nFull review comments:\n\n- [${priority}] ${title} — app.py:1\n  The change is additive and self-contained.\n`;

  // Marker ALONE — the clean verdict, and it yields NO stubs: the marker is a
  // carrier for "nothing found", never a finding the verifier should judge.
  for (const title of [
    "NO-MATERIAL-FINDINGS",
    "no-material-findings",          // case-insensitive
    "No-Material-Findings",
    "**NO-MATERIAL-FINDINGS**",      // emphasized
    "`NO-MATERIAL-FINDINGS`",
    '"NO-MATERIAL-FINDINGS"',
    "NO-MATERIAL-FINDINGS."          // one trailing period of slack
  ]) {
    assert.deepEqual(
      extractStubs(marker(title), "lens-7"), { stubs: [], clean: true, failed: false },
      `marker alone must read clean: ${JSON.stringify(title)}`
    );
  }

  // Any priority: the instruction asks for the lowest, but a finder that files
  // the marker at P0 still means "nothing found".
  assert.deepEqual(extractStubs(marker("NO-MATERIAL-FINDINGS", "P0"), "lens-7"),
    { stubs: [], clean: true, failed: false });

  // A title that merely CONTAINS the marker is a real finding, not the verdict.
  for (const title of ["NO-MATERIAL-FINDINGS in the parser", "Fix NO-MATERIAL-FINDINGS handling"]) {
    const r = extractStubs(marker(title), "lens-7");
    assert.equal(classify(r), "stubs", `must stay a real finding: ${title}`);
    assert.equal(r.stubs.length, 1);
    assert.equal(r.stubs[0].title, title);
  }

  // Marker ALONGSIDE real findings: the model misread "if and only if". Losing
  // the real findings to a stray marker would be the worst outcome, so the
  // marker is dropped and the findings are kept — and because `clean` demands
  // the marker stood ALONE, this can never manufacture a false clean.
  {
    const mixed = `# Codex Review

Full review comments:

- [P2] Move the sweep cursor outside the daemon registry — skills/board-sweep.sh:429
  The cursor is addressable by daemon commands.

- [P3] NO-MATERIAL-FINDINGS — app.py:1
  Otherwise nothing material.

- [P1] Guard the impact cursor — skills/daemon-retire.sh:88-92
  Retirement corrupts the cursor.
`;
    const r = extractStubs(mixed, "lens-8");
    assert.equal(r.clean, false, "a marker beside real findings is not a clean verdict");
    assert.equal(r.failed, false);
    assert.deepEqual(r.stubs.map((s) => s.title),
      ["Move the sweep cursor outside the daemon registry", "Guard the impact cursor"],
      "the marker is dropped, every real finding survives");
    // Ids stay as parsed — they are opaque keys, and the gap is the truth about
    // where each finding sat in the finder's render.
    assert.deepEqual(r.stubs.map((s) => s.id), ["lens-8#1", "lens-8#3"]);
  }

  // The unsentineled clean prose is STILL failed: the marker is the only clean
  // signal on the native path, and silence is never read as "nothing found".
  assert.equal(classify(extractStubs(fx("clean-prose-unsentineled"), "lens-9")), "failed");
}

// ---------------------------------------------------------------------------
// partial-drift.md — r15 with the list marker stripped from the SECOND head
// only. The first finding still parses; handing back that subset would silently
// lose the second. One unconsumed [P#] line makes the whole finder suspect.
// ---------------------------------------------------------------------------
{
  const r = extractStubs(fx("partial-drift"), "lens-5");
  assert.equal(classify(r), "failed", "partial drift must not return a partial subset");
  assert.deepEqual(r, { stubs: [], clean: false, failed: true });
  // Guard against passing for the wrong reason: the intact first head really is
  // parseable on its own, so the failure comes from the drifted second one.
  assert.equal(extractStubs(fx("campaign-r15"), "lens-5").stubs.length, 2);
}

// ---------------------------------------------------------------------------
// Everything that is neither parsed findings nor that clean rendering fails.
// Zero stubs is never silently ok: a dead finder must not read as a clean one.
// ---------------------------------------------------------------------------
for (const name of [
  "blank",          // empty output
  "drifted",        // r15 with the list markers stripped: [P#] present, structure gone
  "untagged-drift", // r15 with tag and location stripped: findings-like prose only
  "empty-stdout",   // render.mjs line 301 — a recognized rendering, but output loss
  "prose-answer",   // a real run that answered in prose instead of the finding format
  "partial-drift"   // only the second head lost its marker — the whole finder is suspect
]) {
  const r = extractStubs(fx(name), "lens-x");
  assert.equal(classify(r), "failed", `${name}.md must classify failed`);
  assert.deepEqual(r, { stubs: [], clean: false, failed: true }, `${name}.md`);
}
for (const empty of [undefined, null, "", "   \n\n  "]) {
  assert.deepEqual(extractStubs(empty, "lens-x"), { stubs: [], clean: false, failed: true });
}

// ---------------------------------------------------------------------------
// SYNTHETIC (not a real render): assembly mechanics no observed render exercises
// — a wrapped multi-line body, and findings with no blank line between them.
// ---------------------------------------------------------------------------
{
  const synthetic = [
    "- [P1] Wrapped body — /a/b.ts:3-9",
    "  first line of the body",
    "  second line of the body",
    "- [P2] Adjacent head with no blank line — /a/c.ts:12",
    "  its body"
  ].join("\n");
  const r = extractStubs(synthetic, "f");
  assert.equal(r.stubs.length, 2);
  assert.equal(r.stubs[0].body, "first line of the body\nsecond line of the body");
  assert.equal(r.stubs[1].id, "f#2");
  assert.equal(r.stubs[1].lines, "12");   // single line number, no range
  assert.equal(r.stubs[1].body, "its body");

  // The em-dash separator is part of the head shape every observed render uses:
  // a list item ending in a bare path:line is drift, not a finding.
  assert.deepEqual(extractStubs("- No separator /a/b.ts:4", "f").stubs, []);

  // The drift guard keys on lines that OPEN like a head. A body that merely
  // mentions a priority mid-sentence is not a mangled head, and must not blow up
  // an otherwise healthy finder.
  const tagInBody = ["- [P1] Healthy finding — /a/b.ts:3", "  downgraded from [P0] after review"].join("\n");
  assert.equal(extractStubs(tagInBody, "f").stubs.length, 1);
  assert.equal(extractStubs(tagInBody, "f").failed, false);
}

console.log("test-panel-extract: ok");
